import {expect,test,type Page} from '@playwright/test';
type AuditEvent={kind:'request'|'play'|'pause';id:string};type AuditState={events:AuditEvent[]};
async function installVoiceAudit(page:Page){await page.addInitScript(()=>{const audit:AuditState={events:[]};const blobIds=new WeakMap<Blob,string>();const nativeFetch=window.fetch.bind(window);const nativeCreateObjectURL=URL.createObjectURL.bind(URL);window.fetch=async(input:RequestInfo|URL,init?:RequestInit)=>{const url=typeof input==='string'?input:input instanceof URL?input.href:input.url;let narrationId='';if(url.includes('/api/narration')){let rawBody=init?.body;if(rawBody==null&&input instanceof Request){try{rawBody=await input.clone().text()}catch{}}if(typeof rawBody==='string'){try{narrationId=(JSON.parse(rawBody) as {id?:string}).id??''}catch{}}if(narrationId)audit.events.push({kind:'request',id:narrationId})}const response=await nativeFetch(input,init);if(!narrationId)return response;return new Proxy(response,{get(target,property){if(property==='blob')return async()=>{const blob=await target.blob();blobIds.set(blob,narrationId);return blob};const value=Reflect.get(target,property,target);return typeof value==='function'?value.bind(target):value}})};URL.createObjectURL=(blob:Blob|MediaSource)=>{if(blob instanceof Blob){const id=blobIds.get(blob);if(id)return'blob:l78-voice/'+encodeURIComponent(id)}return nativeCreateObjectURL(blob)};class MockAudio{src='';preload='';playbackRate=1;currentTime=0;onended:(()=>void)|null=null;onerror:(()=>void)|null=null;private timer:number|null=null;private started=false;constructor(source=''){this.src=source}id(){const prefix='blob:l78-voice/';return this.src.startsWith(prefix)?decodeURIComponent(this.src.slice(prefix.length)):this.src}pause(){if(this.started)audit.events.push({kind:'pause',id:this.id()});this.started=false;if(this.timer!==null){window.clearTimeout(this.timer);this.timer=null}}play(){this.pause();this.started=true;audit.events.push({kind:'play',id:this.id()});this.timer=window.setTimeout(()=>{this.timer=null;this.started=false;this.onended?.()},5000);return Promise.resolve()}}Object.defineProperty(window,'Audio',{configurable:true,writable:true,value:MockAudio});(window as unknown as {__l78Voice:AuditState}).__l78Voice=audit;localStorage.setItem('mathnikita-voice-settings-v4',JSON.stringify({engine:'studio',rate:.94}));localStorage.setItem('mathnikita-mentor-auto-guide','false')})}
async function events(page:Page){return page.evaluate(()=>(window as unknown as {__l78Voice:AuditState}).__l78Voice.events)}
test('lesson 78 immediately stops stale Sulafat and narrates the new stage',async({page})=>{test.setTimeout(90000);await installVoiceAudit(page);await page.route('**/api/narration-status',route=>route.fulfill({status:200,contentType:'application/json',body:JSON.stringify({ok:true,studioConfigured:true,provider:'gemini',voice:'Sulafat'})}));await page.route('**/api/narration',route=>route.fulfill({status:200,contentType:'audio/wav',body:'RIFF-lesson78'}));await page.goto('/');const chapterThree=page.locator('.course-chapter-group').nth(2);if(!(await chapterThree.evaluate(element=>(element as HTMLDetailsElement).open)))await chapterThree.locator('summary').click();await page.getByRole('button',{name:/Открыть урок 78:/}).click();await page.locator('.lesson-opening-start').click();const stage=page.locator('.lesson-runtime:not([hidden]) .interactive-stage[data-stage-id]');await expect(stage).toHaveAttribute('data-stage-id','l78-mission');const prefix='lesson-78-stage-';await expect.poll(async()=>{const audit=await events(page);return audit.filter(event=>event.kind==='play'&&event.id.startsWith(prefix)).at(-1)?.id??''},{timeout:12000}).not.toBe('');const before=await events(page);const oldId=before.filter(event=>event.kind==='play'&&event.id.startsWith(prefix)).at(-1)?.id;expect(oldId).toBeTruthy();await page.evaluate(()=>{(window as unknown as {__l78Voice:AuditState}).__l78Voice.events=[]});await stage.getByRole('button',{name:'Дальше →',exact:true}).dispatchEvent('click');const immediate=await events(page);expect(immediate.some(event=>event.kind==='pause'&&event.id===oldId)).toBeTruthy();await expect(stage).toHaveAttribute('data-stage-id','l78-oral1-model');await expect.poll(async()=>{const audit=await events(page);return audit.some(event=>event.kind==='play'&&event.id.startsWith(prefix)&&event.id!==oldId)},{timeout:12000}).toBeTruthy()});
